import SwiftUI

/**
 * Where an `HKImage` gets its pixels from.
 */
public enum HKImageSource {
    /**
     * Image in the design system's `Media.xcassets`, by name.
     */
    case media(String)

    /**
     * Image in any asset catalog: the app's by default, or the given bundle.
     */
    case asset(String, bundle: Bundle? = nil)

    /**
     * Type-safe asset generated by Xcode, from the app or any package,
     * for example `.resource(.hkPlaceholder)`.
     */
    case resource(ImageResource)

    /**
     * SF Symbol, for example `.system("briefcase.fill")`.
     */
    case system(String)

    /**
     * An image already built elsewhere.
     */
    case image(Image)

    var isSymbol: Bool {
        if case .system = self { true } else { false }
    }

    var image: Image {
        switch self {
        case .media(let name): Image(name, bundle: .module)
        case .asset(let name, let bundle): Image(name, bundle: bundle)
        case .resource(let resource): Image(resource)
        case .system(let name): Image(systemName: name)
        case .image(let image): image
        }
    }
}

public struct HKImageModel {
    public let source: HKImageSource
    public let contentMode: ContentMode
    public let tint: Color?
    public let accessibilityLabel: LocalizedStringKey?

    /**
     * Leave `accessibilityLabel` nil for decorative images so VoiceOver skips them.
     * `tint` colors SF Symbols and template assets.
     */
    public init(
        source: HKImageSource,
        contentMode: ContentMode = .fit,
        tint: Color? = nil,
        accessibilityLabel: LocalizedStringKey? = nil
    ) {
        self.source = source
        self.contentMode = contentMode
        self.tint = tint
        self.accessibilityLabel = accessibilityLabel
    }
}
